"import os\nimport re\n\npatterns = [r'\\bdemo\\b', r'\\bmock\\b', r'\\bjudges\\b', r'\\bhackathon\\b', r'\\bsimulation\\b', r'\\bdummy\\b', r'\\bsample\\b']\nregexes = [re.compile(p, re.IGNORECASE) for p in patterns]\n\nlib_dir = r\"c:\\Women\\she_shield\\lib\"\noutput_file = r\"c:\\Women\\she_shield\\scratch\\matches.txt\"\n\nwith open(output_file, 'w', encoding='utf-8') as out:\n    for root, dirs, files in os.walk(lib_dir):\n        for file in files:\n            if file.endswith('.dart'):\n                filepath = os.path.join(root, file)\n                with open(filepath, 'r', encoding='utf-8') as f:\n                    lines = f.readlines()\n                \n                for idx, line in enumerate(lines):\n                    matched = []\n                    for r in regexes:\n                        if r.search(line):\n                            matched.append(r.pattern)\n                    if matched:\n                        out.write(f\"{os.path.relpath(filepath, lib_dir)}:{idx+1}: {line.strip()} (matches: {', '.join(matched)})\\n\")\nprint(\"Done writing to matches.txt\")\n"